===== AssignOwnerCustomerCode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.util.CustomerCode;
import org.springframework.samples.petclinic.util.OwnerRegion;

/**
 * Assigns a newly built owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where
 * REGION is the owner's {@link OwnerRegion region} (derived from its postcode) and HASH8 is the
 * first 8 upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)} (e.g.
 * 'NSW-1A2B3C4D'). The code is a deterministic function of the owner's region and identity, so on
 * the rare collision with an existing owner's code it is de-duplicated by appending {@code '-<n>'}
 * with the smallest {@code n >= 2} that stays unique. The telephone has already been normalized to
 * E.164 earlier in the pipeline, so {@link Owner#getTelephone()} is the normalized telephone the
 * hash covers. Runs before the owner is persisted, so {@link OwnerRepository#findAll()} returns
 * only the codes taken by existing owners and never the owner itself. The code is stored in place
 * on the built entity so it is persisted and returned; the membership number, its check digit and
 * the locality are all derived from it. Runs after {@link BuildOwner}.
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = OwnerRegion.of(owner.getPostcode(), owner.getCity());
        String code = CustomerCode.of(region, owner.getTelephone(), owner.getLastName());
        Set<String> taken = ownerRepository.findAll().stream()
                .map(Owner::getCustomerCode)
                .filter(Objects::nonNull)
                .collect(Collectors.toSet());
        owner.setCustomerCode(CustomerCode.deduplicate(code, taken));
    }
}
===== AssignOwnerMembershipLevel =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Runs in {@code POST /api/owners} after {@link AssignOwnerMembershipPoints} has recorded the
 * owner's membership points and before it is saved, within the create transaction. Records on the
 * built owner its numeric membership level, derived solely from those points: level 1 for 0-1
 * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
 */
public class AssignOwnerMembershipLevel {

    public void service(@Val Owner owner) {
        owner.setMembershipLevel(levelFor(owner.getMembershipPoints()));
    }

    /** Maps membership points onto the membership level band that contains them. */
    private static int levelFor(int points) {
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }
}
===== AssignOwnerMembershipPoints =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Runs in {@code POST /api/owners} after the owner's household size and namesake count have been
 * recorded and before it is saved, within the create transaction. Records on the built owner its
 * numeric membership points: starting at 0, it gains 2 when an email is present, 1 more when
 * {@link Owner#getNamesakeCount() namesakeCount} is 0, 2 for a household of
 * {@link #LARGE_HOUSEHOLD_MIN} or more members, and 3 when the owner's tenure exceeds
 * {@link #TENURE_DAYS_FOR_BONUS} days. Because a newly registered owner has zero tenure, a new
 * owner never earns the tenure points. Reads the resolved (weekend-adjusted) registration date
 * published by {@link ResolveOwnerRegistrationDate} — the owner is not stamped with it until
 * {@link ApplyOwnerRegistrationDate}, which runs later. {@link AssignOwnerMembershipLevel} maps the
 * points recorded here onto the membership level.
 */
public class AssignOwnerMembershipPoints {

    /** Points earned when the owner has an email address. */
    private static final int EMAIL_POINTS = 2;

    /** Points earned when no existing owner shared the owner's name at creation. */
    private static final int UNIQUE_NAME_POINTS = 1;

    /** Points earned when the owner belongs to a household of {@link #LARGE_HOUSEHOLD_MIN}+. */
    private static final int LARGE_HOUSEHOLD_POINTS = 2;

    /** Smallest household size that earns {@link #LARGE_HOUSEHOLD_POINTS}. */
    private static final int LARGE_HOUSEHOLD_MIN = 3;

    /** Points earned when the owner's tenure exceeds {@link #TENURE_DAYS_FOR_BONUS} days. */
    private static final int LONG_TENURE_POINTS = 3;

    /** Tenure, in days, an owner must exceed to earn {@link #LONG_TENURE_POINTS}. */
    private static final long TENURE_DAYS_FOR_BONUS = 365;

    public void service(@Val Owner owner, @Val LocalDate registrationDate) {
        int points = 0;
        if (hasEmail(owner)) {
            points += EMAIL_POINTS;
        }
        if (hasUniqueName(owner)) {
            points += UNIQUE_NAME_POINTS;
        }
        if (hasLargeHousehold(owner)) {
            points += LARGE_HOUSEHOLD_POINTS;
        }
        if (tenureDays(registrationDate) > TENURE_DAYS_FOR_BONUS) {
            points += LONG_TENURE_POINTS;
        }
        owner.setMembershipPoints(points);
    }

    private static boolean hasEmail(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isEmpty();
    }

    private static boolean hasUniqueName(Owner owner) {
        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
    }

    private static boolean hasLargeHousehold(Owner owner) {
        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= LARGE_HOUSEHOLD_MIN;
    }

    /** Days the owner has been registered as of today; zero (or negative) for a new owner. */
    private static long tenureDays(LocalDate registrationDate) {
        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
    }
}
===== ApplyOwnerRegistrationDate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Stamps the resolved registration date onto the built owner in {@code POST /api/owners}, so
 * it is persisted and returned as ISO 'YYYY-MM-DD' and every value derived from it (such as
 * the membership number's year segment) uses the adjusted business day. The date is resolved
 * by {@link ResolveOwnerRegistrationDate} (supplied-or-server date, rolled off weekends).
 * Runs after {@link BuildOwner} and before the owner is saved.
 */
public class ApplyOwnerRegistrationDate {

    public void service(@Val Owner owner, @Val LocalDate registrationDate) {
        owner.setRegistrationDate(registrationDate);
    }
}
===== ResolveOwnerRegistrationDate =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.util.BusinessDay;

/**
 * Resolves the effective registration date for {@code POST /api/owners}: the date supplied in
 * the body, or the server's current date when none was supplied, rolled forward to the next
 * business day when it falls on a weekend or a public holiday. Publishes it so the daily-capacity check counts
 * against the adjusted business day and {@link ApplyOwnerRegistrationDate} stamps the same
 * value onto the built owner. Runs after validation and before the daily-capacity check.
 */
public class ResolveOwnerRegistrationDate {

    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
        LocalDate supplied = request.getRegistrationDate();
        LocalDate effective = supplied != null ? supplied : LocalDate.now();
        registrationDate.set(BusinessDay.rollForward(effective));
    }
}
===== AuditOwnerCreated =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Emits an audit trail entry for a successful owner create in {@code POST /api/owners}.
 * Publishes a single line to the dedicated {@code AUDIT} logger carrying the persisted
 * owner's id, its assigned {@code customerCode}, its {@code registrationDate}, its assigned
 * {@code membershipLevel} and its derived {@code membershipNumber}. Runs after {@link SaveOwner}
 * so the generated id is available, and before the response is sent.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                owner.getMembershipLevel(), ownerMapper.membershipNumber(owner));
    }
}

