22	     * The age band for someone born on {@code birthDate} as at {@code referenceDate}, using
23	     * completed years.
24	     */
25	    public static String of(LocalDate birthDate, LocalDate referenceDate) {
26	        int years = Period.between(birthDate, referenceDate).getYears();
27	        if (years < 18) {
28	            return MINOR;
29	        }
30	        if (years < 65) {
31	            return ADULT;
32	        }
33	        return SENIOR;
